update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Độ biến thiên động lượng của một vật","answer":3,"options":["$\\overset{\\rightarrow}{F}=m\\overset{\\rightarrow}{\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}}.$","$\\overset{\\rightarrow}{F}=m\\frac{\\Delta v}{\\Delta t}.$","$\\overset{\\rightarrow}{F}=\\overset{\\rightarrow}{\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}}.$","$\\overset{\\rightarrow}{F}=m\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Biểu thức của định luật II Newton còn được viết dưới dạng nào sau đây?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật II Newton: gia tốc của một vật cùng hướng với lực tác dụng lên vật, có độ lớn tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng của vật.</p><p class=\"text-base leading-relaxed my-2\">Biểu thức: $\\overset{\\rightarrow}{F}=m\\overset{\\rightarrow}{a}$, trong đó $\\overset{\\rightarrow}{a}$ là gia tốc.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc là đạo hàm của vận tốc theo thời gian, với độ biến thiên vận tốc trong khoảng thời gian ngắn: $\\overset{\\rightarrow}{a}=\\dfrac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\overset{\\rightarrow}{F}=m\\dfrac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">Đáp án D đúng. Phương án C thiếu khối lượng $m$; phương án B dùng độ lớn $\\Delta v$ thay cho độ biến thiên vectơ vận tốc.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Độ biến thiên động lượng của một vật","answer":3,"options":["$\\overset{\\rightarrow}{F}=m\\overset{\\rightarrow}{\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}}.$","$\\overset{\\rightarrow}{F}=m\\frac{\\Delta v}{\\Delta t}.$","$\\overset{\\rightarrow}{F}=\\overset{\\rightarrow}{\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}}.$","$\\overset{\\rightarrow}{F}=m\\frac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Biểu thức của định luật II Newton còn được viết dưới dạng nào sau đây?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật II Newton: gia tốc của một vật cùng hướng với lực tác dụng lên vật, có độ lớn tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng của vật.</p><p class=\"text-base leading-relaxed my-2\">Biểu thức: $\\overset{\\rightarrow}{F}=m\\overset{\\rightarrow}{a}$, trong đó $\\overset{\\rightarrow}{a}$ là gia tốc.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc là đạo hàm của vận tốc theo thời gian, với độ biến thiên vận tốc trong khoảng thời gian ngắn: $\\overset{\\rightarrow}{a}=\\dfrac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\overset{\\rightarrow}{F}=m\\dfrac{\\Delta\\overset{\\rightarrow}{v}}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">Đáp án D đúng. Phương án C thiếu khối lượng $m$; phương án B dùng độ lớn $\\Delta v$ thay cho độ biến thiên vectơ vận tốc.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544736 and note = 'nap-vl10-c5-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Độ biến thiên động lượng của một vật","answer":1,"options":["$p = \\overset{\\rightarrow}{F}m\\Delta t.$","$p = \\overset{\\rightarrow}{F}\\Delta t.$","$p = \\frac{F}{\\Delta}tm.$","$p = \\overset{\\rightarrow}{F}m.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Cho chất điểm m chuyển động không vận tốc đầu chỉ dưới tác dụng của lực $\\overset{\\rightarrow}{F}$ không đổi. Động lượng chất điểm ở thời điểm t là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Định lí biến thiên động lượng (dạng xung lượng): khi lực $\\overset{\\rightarrow}{F}$ không đổi tác dụng lên chất điểm trong khoảng thời gian $\\Delta t$, độ biến thiên động lượng bằng xung lượng của lực: $\\Delta \\overset{\\rightarrow}{p} = \\overset{\\rightarrow}{F}\\Delta t$.</p><p class=\"text-base leading-relaxed my-2\">Chất điểm bắt đầu chuyển động từ trạng thái nghỉ nên động lượng ban đầu $\\overset{\\rightarrow}{p}_0 = \\overset{\\rightarrow}{0}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\overset{\\rightarrow}{p} - \\overset{\\rightarrow}{p}_0 = \\overset{\\rightarrow}{F}\\Delta t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\overset{\\rightarrow}{p} = \\overset{\\rightarrow}{F}\\Delta t$ (với $\\Delta t = t$ là thời gian tính từ lúc bắt đầu chuyển động).</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án còn lại: A và D có thứ nguyên sai (chứa khối lượng $m$ trong khi động lượng không phụ thuộc trực tiếp như vậy); C bị lỗi công thức và không đúng dạng $\\overset{\\rightarrow}{F}\\Delta t$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>B</b>, $p = F\\Delta t$.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Độ biến thiên động lượng của một vật","answer":1,"options":["$p = \\overset{\\rightarrow}{F}m\\Delta t.$","$p = \\overset{\\rightarrow}{F}\\Delta t.$","$p = \\frac{F}{\\Delta}tm.$","$p = \\overset{\\rightarrow}{F}m.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Cho chất điểm m chuyển động không vận tốc đầu chỉ dưới tác dụng của lực $\\overset{\\rightarrow}{F}$ không đổi. Động lượng chất điểm ở thời điểm t là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Định lí biến thiên động lượng (dạng xung lượng): khi lực $\\overset{\\rightarrow}{F}$ không đổi tác dụng lên chất điểm trong khoảng thời gian $\\Delta t$, độ biến thiên động lượng bằng xung lượng của lực: $\\Delta \\overset{\\rightarrow}{p} = \\overset{\\rightarrow}{F}\\Delta t$.</p><p class=\"text-base leading-relaxed my-2\">Chất điểm bắt đầu chuyển động từ trạng thái nghỉ nên động lượng ban đầu $\\overset{\\rightarrow}{p}_0 = \\overset{\\rightarrow}{0}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\overset{\\rightarrow}{p} - \\overset{\\rightarrow}{p}_0 = \\overset{\\rightarrow}{F}\\Delta t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\overset{\\rightarrow}{p} = \\overset{\\rightarrow}{F}\\Delta t$ (với $\\Delta t = t$ là thời gian tính từ lúc bắt đầu chuyển động).</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án còn lại: A và D có thứ nguyên sai (chứa khối lượng $m$ trong khi động lượng không phụ thuộc trực tiếp như vậy); C bị lỗi công thức và không đúng dạng $\\overset{\\rightarrow}{F}\\Delta t$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>B</b>, $p = F\\Delta t$.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544737 and note = 'nap-vl10-c5-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":0,"options":["${\\overset{\\rightarrow}{p}}_{AB}=m\\left( v \\right)_{1}-v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}= -m\\left( v \\right)_{1}-v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}=m\\left( v \\right)_{1}+v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}= -m\\left( v \\right)_{1}+v_{2}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô A có khối lượng m đang chuyển động với vận tốc $v_{1}$ đuổi theo một ô tô B có khối lượng $m_{2}$ chuyển động với vận tốc $ v_{2}$. Động lượng của xe A đối với hệ quy chiếu gắn với xe B là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của vật trong một hệ quy chiếu được xác định theo vận tốc của vật đối với hệ quy chiếu đó: $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v}$, trong đó $\\overset{\\rightarrow}{v}$ là vận tốc của vật đối với hệ quy chiếu đang xét.</p><p class=\"text-base leading-relaxed my-2\">Vận tốc của xe A đối với xe B (theo quy tắc cộng vận tốc cổ điển): $\\overset{\\rightarrow}{v}_{AB}=\\overset{\\rightarrow}{v}_{1}-\\overset{\\rightarrow}{v}_{2}$, với $\\overset{\\rightarrow}{v}_{1}$ là vận tốc của A và $\\overset{\\rightarrow}{v}_{2}$ là vận tốc của B đối với đường (hệ quy chiếu đứng yên).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Động lượng của xe A đối với hệ quy chiếu gắn với xe B: $\\overset{\\rightarrow}{p}_{AB}=m\\overset{\\rightarrow}{v}_{AB}=m\\left(\\overset{\\rightarrow}{v}_{1}-\\overset{\\rightarrow}{v}_{2}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":0,"options":["${\\overset{\\rightarrow}{p}}_{AB}=m\\left( v \\right)_{1}-v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}= -m\\left( v \\right)_{1}-v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}=m\\left( v \\right)_{1}+v_{2}.$","${\\overset{\\rightarrow}{p}}_{AB}= -m\\left( v \\right)_{1}+v_{2}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Một ô tô A có khối lượng m đang chuyển động với vận tốc $v_{1}$ đuổi theo một ô tô B có khối lượng $m_{2}$ chuyển động với vận tốc $ v_{2}$. Động lượng của xe A đối với hệ quy chiếu gắn với xe B là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của vật trong một hệ quy chiếu được xác định theo vận tốc của vật đối với hệ quy chiếu đó: $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v}$, trong đó $\\overset{\\rightarrow}{v}$ là vận tốc của vật đối với hệ quy chiếu đang xét.</p><p class=\"text-base leading-relaxed my-2\">Vận tốc của xe A đối với xe B (theo quy tắc cộng vận tốc cổ điển): $\\overset{\\rightarrow}{v}_{AB}=\\overset{\\rightarrow}{v}_{1}-\\overset{\\rightarrow}{v}_{2}$, với $\\overset{\\rightarrow}{v}_{1}$ là vận tốc của A và $\\overset{\\rightarrow}{v}_{2}$ là vận tốc của B đối với đường (hệ quy chiếu đứng yên).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Động lượng của xe A đối với hệ quy chiếu gắn với xe B: $\\overset{\\rightarrow}{p}_{AB}=m\\overset{\\rightarrow}{v}_{AB}=m\\left(\\overset{\\rightarrow}{v}_{1}-\\overset{\\rightarrow}{v}_{2}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là A.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544739 and note = 'nap-vl10-c5-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":1,"options":["$m\\overset{\\rightarrow}{v}.$","$m_{1}v_{1}+m_{2}v_{2}.$","0.","$m_{1}v_{1}+m_{2}v_{2}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Hai vật có khối lượng $m_{1},$$m_{2}$ chuyển động với vận tốc ${\\overset{\\rightarrow}{v}}_{1}$ và ${\\overset{\\rightarrow}{v}}_{2}.$ Động lượng của hệ có giá trị</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của một vật là $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v}$. Động lượng của hệ hai vật là tổng vectơ động lượng của từng vật (động lượng là đại lượng vectơ nên phải cộng theo quy tắc hình bình hành):</p><p class=\"text-base leading-relaxed my-2\">$\\overset{\\rightarrow}{p}=\\overset{\\rightarrow}{p_1}+\\overset{\\rightarrow}{p_2}=m_1\\overset{\\rightarrow}{v_1}+m_2\\overset{\\rightarrow}{v_2}$</p><p class=\"text-base leading-relaxed my-2\">Trong các phương án, chỉ có $m_1\\overset{\\rightarrow}{v_1}+m_2\\overset{\\rightarrow}{v_2}$ đúng. Phương án A chỉ đúng khi hệ có một vận tốc chung, còn phương án C chỉ đúng khi tổng động lượng bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của hệ là $m_1\\overset{\\rightarrow}{v_1}+m_2\\overset{\\rightarrow}{v_2}$, chọn <b>B</b>.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":1,"options":["$m\\overset{\\rightarrow}{v}.$","$m_{1}v_{1}+m_{2}v_{2}.$","0.","$m_{1}v_{1}+m_{2}v_{2}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Hai vật có khối lượng $m_{1},$$m_{2}$ chuyển động với vận tốc ${\\overset{\\rightarrow}{v}}_{1}$ và ${\\overset{\\rightarrow}{v}}_{2}.$ Động lượng của hệ có giá trị</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của một vật là $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v}$. Động lượng của hệ hai vật là tổng vectơ động lượng của từng vật (động lượng là đại lượng vectơ nên phải cộng theo quy tắc hình bình hành):</p><p class=\"text-base leading-relaxed my-2\">$\\overset{\\rightarrow}{p}=\\overset{\\rightarrow}{p_1}+\\overset{\\rightarrow}{p_2}=m_1\\overset{\\rightarrow}{v_1}+m_2\\overset{\\rightarrow}{v_2}$</p><p class=\"text-base leading-relaxed my-2\">Trong các phương án, chỉ có $m_1\\overset{\\rightarrow}{v_1}+m_2\\overset{\\rightarrow}{v_2}$ đúng. Phương án A chỉ đúng khi hệ có một vận tốc chung, còn phương án C chỉ đúng khi tổng động lượng bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của hệ là $m_1\\overset{\\rightarrow}{v_1}+m_2\\overset{\\rightarrow}{v_2}$, chọn <b>B</b>.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544740 and note = 'nap-vl10-c5-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":2,"options":["$\\overset{\\rightarrow}{p}=2m{\\overset{\\rightarrow}{v}}_{1}.$","$\\overset{\\rightarrow}{p}=2m{\\overset{\\rightarrow}{v}}_{2}.$","$\\overset{\\rightarrow}{p}=m\\left( {\\overset{\\rightarrow}{v}}_{1} \\right)+{\\overset{\\rightarrow}{v}}_{2}.$","$p=m\\left( v_{1} \\right)+v_{2}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Hai vật có cùng khối lượng m, chuyển động với vận tốc có độ lớn bằng nhau. Hệ thức tính động lượng của hệ hai vật là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của hệ hai vật là tổng véc tơ động lượng của từng vật: $\\overset{\\rightarrow}{p}=\\overset{\\rightarrow}{p_1}+\\overset{\\rightarrow}{p_2}$.</p><p class=\"text-base leading-relaxed my-2\">Với mỗi vật, động lượng là $\\overset{\\rightarrow}{p_i}=m\\overset{\\rightarrow}{v_i}$, nên $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v_1}+m\\overset{\\rightarrow}{v_2}=m\\left(\\overset{\\rightarrow}{v_1}+\\overset{\\rightarrow}{v_2}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">Phương án A và B chỉ đúng khi hai véc tơ vận tốc trùng nhau về cả hướng lẫn độ lớn, đề bài không nói điều này nên loại. Phương án D là đại lượng vô hướng, không đúng vì động lượng là đại lượng véc tơ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là C.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":2,"options":["$\\overset{\\rightarrow}{p}=2m{\\overset{\\rightarrow}{v}}_{1}.$","$\\overset{\\rightarrow}{p}=2m{\\overset{\\rightarrow}{v}}_{2}.$","$\\overset{\\rightarrow}{p}=m\\left( {\\overset{\\rightarrow}{v}}_{1} \\right)+{\\overset{\\rightarrow}{v}}_{2}.$","$p=m\\left( v_{1} \\right)+v_{2}.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Hai vật có cùng khối lượng m, chuyển động với vận tốc có độ lớn bằng nhau. Hệ thức tính động lượng của hệ hai vật là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của hệ hai vật là tổng véc tơ động lượng của từng vật: $\\overset{\\rightarrow}{p}=\\overset{\\rightarrow}{p_1}+\\overset{\\rightarrow}{p_2}$.</p><p class=\"text-base leading-relaxed my-2\">Với mỗi vật, động lượng là $\\overset{\\rightarrow}{p_i}=m\\overset{\\rightarrow}{v_i}$, nên $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v_1}+m\\overset{\\rightarrow}{v_2}=m\\left(\\overset{\\rightarrow}{v_1}+\\overset{\\rightarrow}{v_2}\\right)$.</p><p class=\"text-base leading-relaxed my-2\">Phương án A và B chỉ đúng khi hai véc tơ vận tốc trùng nhau về cả hướng lẫn độ lớn, đề bài không nói điều này nên loại. Phương án D là đại lượng vô hướng, không đúng vì động lượng là đại lượng véc tơ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là C.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544741 and note = 'nap-vl10-c5-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Định luật bảo toàn động lượng cho hệ kín","answer":3,"options":["$m_{1}v_{1}+m_{2}v_{2}+m_{1}v_{1}'+m_{2}v_{2}'=0.$","$m_{1}{\\overset{\\rightarrow}{v}}_{1}+m_{2}{\\overset{\\rightarrow}{v}}_{2}+m_{1}{\\overset{\\rightarrow}{v}}_{1}'+m_{2}{\\overset{\\rightarrow}{v}}_{2}'=\\overset{\\rightarrow}{0}.$","$m_{1}v_{1}+m_{2}v_{2}=m_{1}v_{1}'+m_{2}v_{2}'.$","$m_{1}{\\overset{\\rightarrow}{v}}_{1}+m_{2}{\\overset{\\rightarrow}{v}}_{2}=m_{1}{\\overset{\\rightarrow}{v}}_{1}'+m_{2}{\\overset{\\rightarrow}{v}}_{2}'.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Xét một hệ cô lập gồm hai vật có khối lượng $m_{1}$, $m_{2}$. Hai vật va chạm nhau, vận tốc trước và sau va chạm của mỗi vật theo thứ tự ${\\overset{\\rightarrow}{v}}_{1},$ ${\\overset{\\rightarrow}{v}}_{1}'$ và ${\\overset{\\rightarrow}{v}}_{2},$ ${\\overset{\\rightarrow}{v}}_{2}'.$ Hệ thức định luật bảo toàn động lượng của hệ là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ hai vật là hệ cô lập nên tổng động lượng của hệ được bảo toàn trong quá trình va chạm.</p><p class=\"text-base leading-relaxed my-2\">Động lượng của mỗi vật: $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v}$. Động lượng của hệ trước va chạm là $m_{1}\\overset{\\rightarrow}{v}_{1}+m_{2}\\overset{\\rightarrow}{v}_{2}$, sau va chạm là $m_{1}\\overset{\\rightarrow}{v}_{1}'+m_{2}\\overset{\\rightarrow}{v}_{2}'$.</p><p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: tổng động lượng trước va chạm bằng tổng động lượng sau va chạm.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{1}\\overset{\\rightarrow}{v}_{1}+m_{2}\\overset{\\rightarrow}{v}_{2}=m_{1}\\overset{\\rightarrow}{v}_{1}'+m_{2}\\overset{\\rightarrow}{v}_{2}'$</p><p class=\"text-base leading-relaxed my-2\">Đáp án D. Các phương án A, B, C sai vì hoặc sai dấu/tổng bằng không, hoặc dùng độ lớn vận tốc thay vì vectơ vận tốc.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Định luật bảo toàn động lượng cho hệ kín","answer":3,"options":["$m_{1}v_{1}+m_{2}v_{2}+m_{1}v_{1}'+m_{2}v_{2}'=0.$","$m_{1}{\\overset{\\rightarrow}{v}}_{1}+m_{2}{\\overset{\\rightarrow}{v}}_{2}+m_{1}{\\overset{\\rightarrow}{v}}_{1}'+m_{2}{\\overset{\\rightarrow}{v}}_{2}'=\\overset{\\rightarrow}{0}.$","$m_{1}v_{1}+m_{2}v_{2}=m_{1}v_{1}'+m_{2}v_{2}'.$","$m_{1}{\\overset{\\rightarrow}{v}}_{1}+m_{2}{\\overset{\\rightarrow}{v}}_{2}=m_{1}{\\overset{\\rightarrow}{v}}_{1}'+m_{2}{\\overset{\\rightarrow}{v}}_{2}'.$"],"question":"<p class=\"text-base leading-relaxed my-2\">Xét một hệ cô lập gồm hai vật có khối lượng $m_{1}$, $m_{2}$. Hai vật va chạm nhau, vận tốc trước và sau va chạm của mỗi vật theo thứ tự ${\\overset{\\rightarrow}{v}}_{1},$ ${\\overset{\\rightarrow}{v}}_{1}'$ và ${\\overset{\\rightarrow}{v}}_{2},$ ${\\overset{\\rightarrow}{v}}_{2}'.$ Hệ thức định luật bảo toàn động lượng của hệ là</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ hai vật là hệ cô lập nên tổng động lượng của hệ được bảo toàn trong quá trình va chạm.</p><p class=\"text-base leading-relaxed my-2\">Động lượng của mỗi vật: $\\overset{\\rightarrow}{p}=m\\overset{\\rightarrow}{v}$. Động lượng của hệ trước va chạm là $m_{1}\\overset{\\rightarrow}{v}_{1}+m_{2}\\overset{\\rightarrow}{v}_{2}$, sau va chạm là $m_{1}\\overset{\\rightarrow}{v}_{1}'+m_{2}\\overset{\\rightarrow}{v}_{2}'$.</p><p class=\"text-base leading-relaxed my-2\">Định luật bảo toàn động lượng: tổng động lượng trước va chạm bằng tổng động lượng sau va chạm.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m_{1}\\overset{\\rightarrow}{v}_{1}+m_{2}\\overset{\\rightarrow}{v}_{2}=m_{1}\\overset{\\rightarrow}{v}_{1}'+m_{2}\\overset{\\rightarrow}{v}_{2}'$</p><p class=\"text-base leading-relaxed my-2\">Đáp án D. Các phương án A, B, C sai vì hoặc sai dấu/tổng bằng không, hoặc dùng độ lớn vận tốc thay vì vectơ vận tốc.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544767 and note = 'nap-vl10-c5-20261020';
update public.question_bank set question = $q${"form":"bai_tap","type":"multiple_choice","topic":"Va chạm mềm, va chạm đàn hồi","answer":0,"options":["$v'=2v.$","$v'=0,5v.$","Va chạm trên gọi là va chạm mềm.","$\\overset{\\rightarrow}{v}'$ cùng phương và cùng chiều $\\overset{\\rightarrow}{v}.$ \n<strong>[TRẮC NGHIỆM ĐỊNH LƯỢNG</strong>"],"question":"<p class=\"text-base leading-relaxed my-2\">Hai viên bi A và B có cùng khối lượng. Bi B đứng yên, bi A chuyển động với vận tốc là $\\overset{\\rightarrow}{v}$ trên mặt phẳng ngang va chạm vào bi B. Sau va chạm hai viên bi dính vào nhau và chuyển động cùng vận tốc $\\overset{\\rightarrow}{v}'$. Điều nào sau đây <strong>sai</strong>?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ hai viên bi là hệ kín trong thời gian va chạm (ngoại lực như trọng lực và phản lực của mặt phẳng ngang cân bằng nhau), nên áp dụng định luật bảo toàn động lượng.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều của $\\overset{\\rightarrow}{v}$. Động lượng trước va chạm: $p_{\\text{trước}} = m_A v + m_B \\cdot 0 = mv$.</p><p class=\"text-base leading-relaxed my-2\">Sau va chạm hai bi dính vào nhau, chuyển động với vận tốc $v'$, tổng khối lượng $2m$: $p_{\\text{sau}} = (m_A + m_B)v' = 2mv'$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Bảo toàn động lượng: $mv = 2mv'$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$v' = \\dfrac{v}{2} = 0{,}5v$, với $\\overset{\\rightarrow}{v}'$ cùng phương, cùng chiều $\\overset{\\rightarrow}{v}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $v' = 2v$ là sai, vì kết quả đúng là $v' = 0{,}5v$.</p><p class=\"text-base leading-relaxed my-2\">B. $v' = 0{,}5v$ là đúng.</p><p class=\"text-base leading-relaxed my-2\">C. Hai vật dính vào nhau sau va chạm là va chạm mềm, đúng.</p><p class=\"text-base leading-relaxed my-2\">D. Vận tốc $\\overset{\\rightarrow}{v}'$ cùng phương, cùng chiều $\\overset{\\rightarrow}{v}$, đúng.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phương án sai là A.</p>","difficultySource":"ai"}$q$::jsonb, content_hash = public.question_content_hash($q${"form":"bai_tap","type":"multiple_choice","topic":"Va chạm mềm, va chạm đàn hồi","answer":0,"options":["$v'=2v.$","$v'=0,5v.$","Va chạm trên gọi là va chạm mềm.","$\\overset{\\rightarrow}{v}'$ cùng phương và cùng chiều $\\overset{\\rightarrow}{v}.$ \n<strong>[TRẮC NGHIỆM ĐỊNH LƯỢNG</strong>"],"question":"<p class=\"text-base leading-relaxed my-2\">Hai viên bi A và B có cùng khối lượng. Bi B đứng yên, bi A chuyển động với vận tốc là $\\overset{\\rightarrow}{v}$ trên mặt phẳng ngang va chạm vào bi B. Sau va chạm hai viên bi dính vào nhau và chuyển động cùng vận tốc $\\overset{\\rightarrow}{v}'$. Điều nào sau đây <strong>sai</strong>?</p>","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hệ hai viên bi là hệ kín trong thời gian va chạm (ngoại lực như trọng lực và phản lực của mặt phẳng ngang cân bằng nhau), nên áp dụng định luật bảo toàn động lượng.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều của $\\overset{\\rightarrow}{v}$. Động lượng trước va chạm: $p_{\\text{trước}} = m_A v + m_B \\cdot 0 = mv$.</p><p class=\"text-base leading-relaxed my-2\">Sau va chạm hai bi dính vào nhau, chuyển động với vận tốc $v'$, tổng khối lượng $2m$: $p_{\\text{sau}} = (m_A + m_B)v' = 2mv'$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Bảo toàn động lượng: $mv = 2mv'$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$v' = \\dfrac{v}{2} = 0{,}5v$, với $\\overset{\\rightarrow}{v}'$ cùng phương, cùng chiều $\\overset{\\rightarrow}{v}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $v' = 2v$ là sai, vì kết quả đúng là $v' = 0{,}5v$.</p><p class=\"text-base leading-relaxed my-2\">B. $v' = 0{,}5v$ là đúng.</p><p class=\"text-base leading-relaxed my-2\">C. Hai vật dính vào nhau sau va chạm là va chạm mềm, đúng.</p><p class=\"text-base leading-relaxed my-2\">D. Vận tốc $\\overset{\\rightarrow}{v}'$ cùng phương, cùng chiều $\\overset{\\rightarrow}{v}$, đúng.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phương án sai là A.</p>","difficultySource":"ai"}$q$::jsonb), updated_at = now() where id = 1544771 and note = 'nap-vl10-c5-20261020';
